<script setup lang="ts">
import { supportedLanguage } from '~~/shared/languages'

definePageMeta({layout:'consumer'})
const { locale, setLocale, t } = useI18n()
const preferredLanguage = ref(locale.value)
const {profiles,profileId,request,requireSession,loadProfiles,selectProfile,signOut}=useConsumer()
const name=ref(''),renaming=ref(''),renameValue=ref(''),displayName=ref(''),email=ref(''),productEmails=ref(false),links=ref<{id:string;shareUrl:string;expiresAt:string|null;isActive:boolean;createdAt:string}[]>([])
const expiry=ref(7),account=ref<Record<string,unknown>>({}),error=ref(''),message=ref(''),busy=ref(false),loading=ref(true),shareUrl=ref('')
useHead({title:'You | Doclyzer'})
async function load(){loading.value=true;error.value='';try{await loadProfiles();const [a,p]=await Promise.all([request<Record<string,unknown>>('/account/profile'),request<{productEmails:boolean}>('/account/communication-preferences')]);account.value=a;preferredLanguage.value=supportedLanguage(a.preferredLanguage);displayName.value=String(a.displayName??'');email.value=String(a.email??'');productEmails.value=p.productEmails;await loadLinks()}catch(cause){error.value=(cause as Error).message}finally{loading.value=false}}
async function loadLinks(){const id=profileId.value;links.value=[];shareUrl.value='';const rows=id?await request<typeof links.value>(`/sharing/links?profileId=${encodeURIComponent(id)}`):[];if(id===profileId.value)links.value=rows}
onMounted(async()=>{if(await requireSession())await load()});watch(profileId,()=>{if(!loading.value)void loadLinks()})
async function act(task:()=>Promise<unknown>,success:string){busy.value=true;error.value='';message.value='';try{await task();message.value=success}catch(cause){error.value=(cause as Error).message}finally{busy.value=false}}
async function addProfile(){if(!name.value.trim())return;await act(async()=>{const p=await request<{id:string}>('/profiles',{method:'POST',body:{name:name.value.trim()}});name.value='';await loadProfiles();await selectProfile(p.id)},t('profileAdded'))}
async function renameProfile(id:string){if(!renameValue.value.trim())return;await act(async()=>{await request(`/profiles/${id}`,{method:'PATCH',body:{name:renameValue.value.trim()}});renaming.value='';await loadProfiles()},t('profileUpdatedWeb'))}
async function removeProfile(id:string){if(!confirm('Delete this profile? Its associated reports may also be removed.'))return;await act(async()=>{await request(`/profiles/${id}`,{method:'DELETE'});await loadProfiles()},t('profileDeleted'))}
async function saveAccount(){await act(async()=>{await request('/account/profile',{method:'PATCH',body:{displayName:displayName.value,preferredLanguage:preferredLanguage.value}});await setLocale(supportedLanguage(preferredLanguage.value));await request('/account/communication-preferences',{method:'PUT',body:{productEmails:productEmails.value}})},t('settingsSaved'))}
async function createLink(){await act(async()=>{const link=await request<{shareUrl:string}>('/sharing/links',{method:'POST',body:{profileId:profileId.value,expiresAt:new Date(Date.now()+expiry.value*86400000).toISOString()}});shareUrl.value=link.shareUrl;await loadLinks();shareUrl.value=link.shareUrl},t('linkCreated'))}
async function revoke(id:string){if(!confirm('Revoke this link? Anyone using it will lose access.'))return;await act(async()=>{await request(`/sharing/links/${id}`,{method:'DELETE'});await loadLinks()},t('linkRevoked'))}
async function copy(url:string){await navigator.clipboard.writeText(url);message.value=t('linkCopied')}
</script>
<template><div><header class="page-heading"><div><p class="eyebrow">{{ t('accountFamily') }}</p><h1>{{ t('you') }}</h1><p class="muted">{{ t('accountIntro') }}</p></div></header><p v-if="loading" role="status">{{ t('loadingSettings') }}</p><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="message" role="status" class="alert success">{{ message }}</p><template v-if="!loading"><section class="card"><h2>{{ t('profiles') }}</h2><div v-for="p in profiles" :key="p.id" class="row profile"><span><strong>{{ p.name }}</strong> <span v-if="p.id===profileId">{{ t('viewingNow') }}</span></span><div class="actions"><button v-if="p.id!==profileId" class="secondary" @click="act(()=>selectProfile(p.id),'Profile switched.')">{{ t('switch') }}</button><button class="secondary" @click="renaming=p.id;renameValue=p.name">{{ t('rename') }}</button><button class="text-button" :disabled="busy" @click="removeProfile(p.id)">{{ t('delete') }}</button></div><form v-if="renaming===p.id" class="row" @submit.prevent="renameProfile(p.id)"><label class="field">{{ t('profileName') }}<input v-model="renameValue" maxlength="100" required /></label><button :disabled="busy">{{ t('saveName') }}</button><button type="button" class="secondary" @click="renaming=''">{{ t('cancel') }}</button></form></div><form class="row" @submit.prevent="addProfile"><label class="field">{{ t('addFamilyProfile') }}<input v-model="name" maxlength="100" :placeholder="t('name')" required /></label><button :disabled="busy">{{ t('addProfile') }}</button></form></section><section class="card"><h2>{{ t('sharing') }}</h2><p>{{ t('shareScope', { name: profiles.find(p=>p.id===profileId)?.name ?? '' }) }}</p><div v-if="profileId" class="row"><label class="field">{{ t('linkExpiresAfter') }}<select v-model.number="expiry"><option :value="1">{{ t('oneDay') }}</option><option :value="7">{{ t('sevenDays') }}</option><option :value="30">{{ t('thirtyDays') }}</option></select></label><button :disabled="busy" @click="createLink">{{ t('createShareLink') }}</button></div><div v-if="shareUrl" class="alert success"><p>{{ t('shareLinkHelp') }}</p><input :value="shareUrl" readonly aria-label="New share link" /><button class="secondary" @click="copy(shareUrl)">{{ t('copy') }}</button></div><div v-for="link in links" :key="link.id" class="row share"><div><strong>{{ link.isActive ? t('activeLink') : t('revokedLink') }}</strong><p>{{ t('linkExpires', { date: link.expiresAt ? new Date(link.expiresAt).toLocaleString(locale) : t('never') }) }}</p></div><div class="actions"><button v-if="link.isActive" class="secondary" @click="copy(link.shareUrl)">{{ t('copy') }}</button><button v-if="link.isActive" class="secondary" :disabled="busy" @click="revoke(link.id)">{{ t('revoke') }}</button></div></div><p v-if="!links.length">{{ t('noShareLinks') }}</p></section><section class="card"><h2>{{ t('account') }}</h2><p v-if="email">{{ email }}</p><form class="stack" @submit.prevent="saveAccount"><LanguageSelector v-model="preferredLanguage" :disabled="busy" /><p class="muted">{{ t('languageHelp') }}</p><label class="field">{{ t('displayName') }}<input v-model="displayName" maxlength="100" /></label><label><input v-model="productEmails" type="checkbox" />{{ t('productEmails') }}</label><div><button :disabled="busy">{{ t('saveSettings') }}</button></div></form></section><section class="card"><h2>{{ t('privacyAccess') }}</h2><div class="actions"><button class="secondary" :disabled="busy" @click="act(()=>request('/account/data-export-requests',{method:'POST',body:{}}),'Data export requested. Check your email for updates.')">{{ t('requestExport') }}</button><NuxtLink class="button secondary" to="/you/sessions">{{ t('manageSessions') }}</NuxtLink><NuxtLink class="button secondary" to="/you/close-account">{{ t('closeAccount') }}</NuxtLink></div></section><button class="secondary" @click="signOut">{{ t('signOut') }}</button></template></div></template>
<style scoped>.share,.profile{border-top:1px solid #dce6dc;padding:12px 0}.profile form{width:100%}.share p{margin:4px 0}.alert input{width:min(100%,500px);padding:9px;margin-right:8px}</style>
